mapper.select:
SELECT EXISTS(
    SELECT 1 FROM tb_follow
    WHERE user_id = #{userId} AND bar_id = #{barId}
)

SELECT f.id, f.user_id AS userId, f.bar_id AS barId, f.create_time AS createTime FROM tb_follow f JOIN tb_bar b ON b.id = f.bar_id WHERE f.user_id = #{userId}
AND b.name ILIKE '%' || #{keyword} || '%' ESCAPE '\'
ORDER BY f.create_time DESC, f.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT bar_id
FROM tb_follow
WHERE user_id = #{userId}
  AND bar_id IN

    #{id}

SELECT user_id
FROM tb_follow
WHERE bar_id = #{barId}

SELECT COUNT(*)
FROM tb_follow
WHERE bar_id = #{barId}

SELECT f.id, f.user_id AS userId, f.bar_id AS barId, f.create_time AS createTime
FROM tb_follow f
WHERE f.bar_id = #{barId}
ORDER BY f.create_time DESC, f.id DESC
LIMIT #{limit} OFFSET #{offset}
